// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }
    function testFuzz_property(address randomCaller) public {
        vm.assume(randomCaller != address(0));
        vm.prank(randomCaller);
        bytes32 uuid = c.proxiableUUID();
        bytes32 expectedSlot = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        assertTrue(uuid == expectedSlot);
    }
}
